//! Culture data and locale-aware formatting and parsing for Power BI's model cultures
//! (`Model.Culture`, e.g. `fr-FR`), shared by the DAX evaluator, Power Query (M), the viewer and
//! the PNG renderer.
//!
//! The table ([`Locale::get`]) is generated by `tools/locale-oracle/gen_data.mjs` from two
//! sources (see `SOURCE.txt` and `docs/formats/locales.md`):
//! - Unicode CLDR (the separators, percent pattern and first day of the week Desktop's visuals
//!   use, and names where nothing was observed);
//! - what the Analysis Services engine of Power BI Desktop returns for our own `FORMAT` corpus
//!   (number separators, currency layout, date/time patterns, AM/PM designators and the names
//!   `FORMAT` prints), which wins where it differs from CLDR;
//! - what Power Query in Desktop returns for our M corpus (the names, month-day and year-month
//!   patterns and percent layout of `Date.ToText` / `Number.ToText`).
//!
//! Modules:
//! - [`calendar`]: calendar math (civil dates, serials, months, weeks) through `jiff`;
//! - [`datefmt`]: .NET-style date/time patterns (`dddd d MMMM yyyy`), used by M and by
//!   [`vb`] for the named formats;
//! - [`vb`]: DAX `FORMAT` format strings (`#,0.00`, `Currency`, `Long Date`, `dd/mm/yyyy`, …);
//! - [`number`]: digit-level helpers (rounding, grouping, the general format);
//! - [`parse`]: text → number the way DAX `VALUE` reads it, with the culture's separators and
//!   currency symbol;
//! - [`display`]: the display units (K/M/bn per language) and number layout of visuals.
//!
//! Everything is pure Rust with no I/O; unknown cultures fall back to their language, then to
//! `en-US` (see [`Locale::get`]).

pub mod calendar;
mod data;
pub mod datefmt;
pub mod display;
pub mod number;
pub mod parse;
pub mod vb;

/// Text written before and after a number (`$` + `1,234.50`, `-` … ` €`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Affix {
    pub prefix: &'static str,
    pub suffix: &'static str,
}

/// A currency layout: symbol, text around the digits of positive and negative amounts, digits
/// after the decimal separator and the separators.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Currency {
    pub symbol: &'static str,
    pub positive: Affix,
    pub negative: Affix,
    pub digits: u8,
    pub decimal: char,
    pub group: char,
}

/// What Power Query (.NET) uses where it differs from DAX `FORMAT` (observed in Desktop).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PowerQuery {
    /// `Number.ToText(x, "C")`, and the currency symbol and separators `Number.FromText` also
    /// accepts (de-AT: `.` groups, fr-CH: `.` is a decimal separator).
    pub currency: Currency,
    /// Groups of two digits after the first three (`12,34,567.89` in en-IN).
    pub indian_grouping: bool,
}

/// What DAX `FORMAT` prints where it differs from the .NET-style data of [`Locale`]
/// (observed on the engine of Power BI Desktop).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Vb {
    /// `Medium Date` as a .NET-style pattern (`dd-MMM-yy`).
    pub medium_date: &'static str,
    /// `Medium Time` (`hh:mm tt`; a culture without designators prints a trailing space).
    pub medium_time: &'static str,
    /// Custom tokens (`mmm`, `dddd`) print English names (ja, zh, ko); `Long Date` keeps the
    /// culture's own pattern.
    pub english_names: bool,
    pub months: [&'static str; 12],
    /// Months after a day number (`d mmmm`: ru "марта").
    pub months_genitive: [&'static str; 12],
    pub months_abbr: [&'static str; 12],
    /// Abbreviated months after a day number (`Medium Date`, `dd mmm`).
    pub months_abbr_genitive: [&'static str; 12],
    pub days: [&'static str; 7],
    pub days_abbr: [&'static str; 7],
    /// First day of the week for `w` and `ww`: 0 = Sunday, 1 = Monday.
    pub first_day: u8,
    /// Week 1 of `ww`: the week of 1 January (0), the first full week (1), the first week with
    /// four days (2).
    pub first_week: u8,
    /// `Yes`, `No`, `True`, `False`, `On`, `Off`.
    pub words: [&'static str; 6],
}

/// How Desktop's visuals lay out numbers (CLDR, with Power BI's display-unit suffixes).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Display {
    pub decimal: char,
    pub group: char,
    /// 2: a 4-digit integer part is not grouped (es: `1234`, `12.345`).
    pub min_grouping: u8,
    /// Percent sign and the text around the number (`50 %` in fr: suffix `"\u{a0}%"`).
    pub percent: Affix,
    /// Suffixes of thousands, millions, billions, trillions (`K`, `M`, `bn`, `T`), including
    /// the space they need.
    pub units: [&'static str; 4],
}

/// One culture.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Locale {
    /// Culture name (`fr-FR`).
    pub name: &'static str,
    /// Decimal and digit-group separators of formatted numbers (DAX `FORMAT`, Power Query).
    pub decimal: char,
    pub group: char,
    /// DAX `FORMAT`'s `Currency` (en-US negative: `($` … `)`) and the currency symbol `VALUE`
    /// accepts.
    pub currency: Currency,
    /// Power Query's own number data.
    pub pq: PowerQuery,
    pub date_separator: &'static str,
    pub time_separator: &'static str,
    /// .NET-style patterns: `/` and `:` stand for the separators above, quoted text is literal.
    pub short_date: &'static str,
    pub long_date: &'static str,
    pub long_time: &'static str,
    pub short_time: &'static str,
    /// AM/PM designators (empty in most 24-hour cultures).
    pub am: &'static str,
    pub pm: &'static str,
    /// .NET `M` and `Y` patterns (`MMMM d`, `d MMMM`; `MMMM yyyy`).
    pub month_day: &'static str,
    pub year_month: &'static str,
    /// .NET `P` layout around the number (`25,6 %` in fr-FR: suffix `" %"`).
    pub percent: Affix,
    /// Names as Power Query (.NET) prints them; the genitive forms follow a day number.
    pub months: [&'static str; 12],
    pub months_genitive: [&'static str; 12],
    pub months_abbr: [&'static str; 12],
    pub months_abbr_genitive: [&'static str; 12],
    pub days: [&'static str; 7],
    pub days_abbr: [&'static str; 7],
    /// First day of the week: 0 = Sunday, 1 = Monday, 6 = Saturday.
    pub first_day: u8,
    pub vb: Vb,
    pub display: Display,
}

const EN_MONTHS: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];
const EN_MONTHS_ABBR: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const EN_DAYS: [&str; 7] = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
];
const EN_DAYS_ABBR: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

const INVARIANT_CURRENCY: Currency = Currency {
    symbol: "\u{a4}",
    positive: Affix {
        prefix: "\u{a4}",
        suffix: "",
    },
    negative: Affix {
        prefix: "(\u{a4}",
        suffix: ")",
    },
    digits: 2,
    decimal: '.',
    group: ',',
};

/// The invariant culture (.NET's `CultureInfo.InvariantCulture`).
static INVARIANT: Locale = Locale {
    name: "",
    decimal: '.',
    group: ',',
    currency: INVARIANT_CURRENCY,
    pq: PowerQuery {
        currency: INVARIANT_CURRENCY,
        indian_grouping: false,
    },
    date_separator: "/",
    time_separator: ":",
    short_date: "MM/dd/yyyy",
    long_date: "dddd, dd MMMM yyyy",
    long_time: "HH:mm:ss",
    short_time: "HH:mm",
    am: "AM",
    pm: "PM",
    month_day: "MMMM dd",
    year_month: "yyyy MMMM",
    percent: Affix {
        prefix: "",
        suffix: " %",
    },
    months: EN_MONTHS,
    months_genitive: EN_MONTHS,
    months_abbr: EN_MONTHS_ABBR,
    months_abbr_genitive: EN_MONTHS_ABBR,
    days: EN_DAYS,
    days_abbr: EN_DAYS_ABBR,
    first_day: 0,
    vb: Vb {
        medium_date: "dd'-'MMM'-'yy",
        medium_time: "hh:mm' 'tt",
        english_names: false,
        months: EN_MONTHS,
        months_genitive: EN_MONTHS,
        months_abbr: EN_MONTHS_ABBR,
        months_abbr_genitive: EN_MONTHS_ABBR,
        days: EN_DAYS,
        days_abbr: EN_DAYS_ABBR,
        first_day: 0,
        first_week: 0,
        words: ["Yes", "No", "True", "False", "On", "Off"],
    },
    display: Display {
        decimal: '.',
        group: ',',
        min_grouping: 1,
        percent: Affix {
            prefix: "",
            suffix: "%",
        },
        units: ["K", "M", "bn", "T"],
    },
};

/// Longest culture name looked up (longer names are not cultures).
const MAX_NAME: usize = 85;

impl Locale {
    /// The culture `name` (`fr-FR`, `FR_fr`, `fr`): the exact culture when the table has it,
    /// else the table's first culture of the same language (`fr-LU` → `fr-FR`), else `en-US`.
    /// An empty name, `iv` or `invariant` is the invariant culture.
    pub fn get(name: &str) -> &'static Locale {
        Locale::find(name).unwrap_or_else(Locale::en_us)
    }

    /// Like [`Locale::get`], but `None` for a language the table does not have.
    pub fn find(name: &str) -> Option<&'static Locale> {
        let name = name.trim();
        if name.len() > MAX_NAME {
            return None;
        }
        let norm = name.replace('_', "-");
        if norm.is_empty() || norm.eq_ignore_ascii_case("iv") || norm.eq_ignore_ascii_case("invariant") {
            return Some(&INVARIANT);
        }
        if let Some(l) = data::LOCALES.iter().find(|l| l.name.eq_ignore_ascii_case(&norm)) {
            return Some(l);
        }
        let lang = norm.split('-').next().unwrap_or("");
        // Script subtags (`sr-Latn-RS`) and regions the table lacks: same language.
        data::LOCALES
            .iter()
            .find(|l| l.language().eq_ignore_ascii_case(lang))
    }

    /// The `en-US` culture (also the fallback of unknown cultures).
    pub fn en_us() -> &'static Locale {
        data::LOCALES.first().unwrap_or(&INVARIANT)
    }

    /// The invariant culture.
    pub fn invariant() -> &'static Locale {
        &INVARIANT
    }

    /// Every culture of the table (not the invariant one).
    pub fn all() -> &'static [Locale] {
        data::LOCALES
    }

    /// The language subtag (`fr` of `fr-FR`).
    pub fn language(&self) -> &'static str {
        self.name.split('-').next().unwrap_or("")
    }

    /// True for the invariant culture.
    pub fn is_invariant(&self) -> bool {
        self.name.is_empty()
    }

    /// The names .NET patterns print in this culture (Power Query).
    pub fn names(&self) -> datefmt::Names<'_> {
        datefmt::Names {
            months: &self.months,
            months_genitive: &self.months_genitive,
            months_abbr: &self.months_abbr,
            months_abbr_genitive: &self.months_abbr_genitive,
            days: &self.days,
            days_abbr: &self.days_abbr,
            am: self.am,
            pm: self.pm,
            date_separator: self.date_separator,
            time_separator: self.time_separator,
        }
    }

    /// The names DAX `FORMAT` prints in this culture.
    pub fn vb_names(&self) -> datefmt::Names<'_> {
        datefmt::Names {
            months: &self.vb.months,
            months_genitive: &self.vb.months_genitive,
            months_abbr: &self.vb.months_abbr,
            months_abbr_genitive: &self.vb.months_abbr_genitive,
            days: &self.vb.days,
            days_abbr: &self.vb.days_abbr,
            am: self.am,
            pm: self.pm,
            date_separator: self.date_separator,
            time_separator: self.time_separator,
        }
    }

    /// The English names `FORMAT`'s custom tokens print in ja, zh and ko.
    pub(crate) fn english_names(&self) -> datefmt::Names<'static> {
        datefmt::Names {
            months: &EN_MONTHS,
            months_genitive: &EN_MONTHS,
            months_abbr: &EN_MONTHS_ABBR,
            months_abbr_genitive: &EN_MONTHS_ABBR,
            days: &EN_DAYS,
            days_abbr: &EN_DAYS_ABBR,
            am: self.am,
            pm: self.pm,
            date_separator: self.date_separator,
            time_separator: self.time_separator,
        }
    }

    /// True when the short date writes the day before the month (`dd/MM/yyyy`).
    pub fn day_first(&self) -> bool {
        match (self.short_date.find('d'), self.short_date.find('M')) {
            (Some(d), Some(m)) => d < m,
            _ => false,
        }
    }

    /// True when the short date starts with the year (`yyyy-MM-dd`).
    pub fn year_first(&self) -> bool {
        self.short_date.trim_start_matches('\'').starts_with('y')
    }

    /// True when the long time uses a 12-hour clock.
    pub fn hour12(&self) -> bool {
        self.long_time.contains('h')
    }
}

